+    assert!(woke.load(std::sync::atomic::Ordering::Relaxed) >= 4, "each request woke the owner");
+
+    // Dropping the inbox stops and joins the listener promptly, and the
+    // port is free again.
+    let t = Instant::now();
+    drop(inbox);
